// ============================================================================
// NÓ: ANÁLISE DE CONSULTA v1.0 (SUPABASE NATIVO)
// ============================================================================

try {
  var dadosWhatsApp = $('Normalizar Dados v2').first().json;
  var dadosIntencao = $('Valida contexto').first().json;
  var consultas = items.map(item => item.json);
} catch (error) {
  return {
    json: {
      encontrou: false,
      erro: "ERRO CRÍTICO: Nós anteriores não encontrados",
      erro_tecnico: error.message,
      deve_pular_atualizacao: true,
      mensagem_para_usuario: "Desculpe, houve um erro técnico. Um atendente entrará em contato."
    }
  };
}

const remoteJid = dadosWhatsApp.telefone_whatsapp || "";
const intencaoUsuario = dadosIntencao.intencao_detectada || "DESCONHECIDO";

if (consultas.length === 0 || !consultas[0].id) {
  return {
    json: {
      encontrou: false,
      erro: "Nenhuma consulta encontrada no Supabase",
      deve_pular_atualizacao: true,
      mensagem_para_usuario: "Não encontrei consulta com seu telefone. Verifique se está marcada ou entre em contato."
    }
  };
}

const consultaEscolhida = consultas[0];

// Formata data e hora
const dataEvento = new Date(consultaEscolhida.data_hora);
const dataFormatada = dataEvento.toLocaleDateString('pt-BR', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  timeZone: 'America/Sao_Paulo'
});

const horaFormatada = dataEvento.toLocaleTimeString('pt-BR', {
  hour: '2-digit',
  minute: '2-digit',
  timeZone: 'America/Sao_Paulo'
});

// Idempotência
const statusAtual = consultaEscolhida.status;
const intencaoToStatus = {
  CONFIRMADO: 'confirmado',
  CANCELADO: 'cancelado',
  REMARCAR: 'remarcado'
};
const statusEsperado = intencaoToStatus[intencaoUsuario];

if (statusEsperado && statusAtual === statusEsperado) {
  let mensagemDuplicidade;
  if (intencaoUsuario === "CONFIRMADO") {
    mensagemDuplicidade = `✅ Sua consulta do dia ${dataFormatada} às ${horaFormatada} já foi confirmada anteriormente.`;
  } else if (intencaoUsuario === "CANCELADO") {
    mensagemDuplicidade = `❌ Sua consulta do dia ${dataFormatada} já foi cancelada anteriormente.`;
  } else {
    mensagemDuplicidade = "Esta ação já foi processada anteriormente.";
  }

  return {
    json: {
      encontrou: true,
      bloqueado_idempotencia: true,
      motivo: `Consulta já estava ${intencaoUsuario}`,
      id_evento_encontrado: consultaEscolhida.id,
      titulo: consultaEscolhida.tipo || "Consulta",
      data_evento: dataFormatada,
      hora_evento: horaFormatada,
      status_agenda: `JA_${intencaoUsuario}`,
      deve_pular_atualizacao: true,
      mensagem_para_usuario: mensagemDuplicidade
    }
  };
}

return {
  json: {
    encontrou: true,
    bloqueado_idempotencia: false,
    id_evento_encontrado: consultaEscolhida.id,
    titulo: consultaEscolhida.tipo || "Consulta",
    data_evento: dataFormatada,
    hora_evento: horaFormatada,
    inicio: consultaEscolhida.data_hora,
    status_agenda: "PENDENTE",
    deve_pular_atualizacao: false,
    intencao_usuario: intencaoUsuario
  }
};

// ============================================================================
// CLEANUP DE SESSÃO v1.5 - DEBUG + FIX
// Já entrega os dados formatados para os próximos nós. ============================================================================

let sessao, intencao, mensagemUsuario, nomePaciente, confianca;

// --- OBTENÇÃO DE DADOS ---
try {
  sessao = $('Valida Expira??o').first().json;
  console.log("✅ Sessão obtida:", JSON.stringify(sessao));
} catch (e) {
  console.log("❌ Erro ao obter sessão:", e.message);
  return [];
}

if (!sessao || !sessao.telefone) {
  console.log("❌ Sessão inválida:", sessao);
  return [];
}

// --- DEBUG: MOSTRAR STATUS ---
console.log("🔍 DEBUG sessao_status:", sessao.sessao_status);
console.log("🔍 DEBUG tipo:", typeof sessao.sessao_status);

try {
  intencao = $('Valida contexto').first().json.intencao_detectada || "DESCONHECIDO";
  mensagemUsuario = $('Normalizar Dados v2').first().json.mensagem_do_usuario || "";
  nomePaciente = $('Webhook').first().json.body.senderName || "Paciente";
  confianca = $('Valida contexto').first().json.confianca_percentual || 0;
} catch (e) {
  console.log("⚠️ Usando defaults para outros campos");
  intencao = "DESCONHECIDO";
  mensagemUsuario = "";
  nomePaciente = "Paciente";
  confianca = 0;
}

// --- VALIDAÇÃO FLEXÍVEL (ACEITA VARIAÇÕES) ---
const statusesValidos = ["VALIDA", "VÁLIDA", "Validada", "EXPIRADA", "Expirada"];

if (!statusesValidos.includes(sessao.sessao_status)) {
  console.log(`❌ Status '${sessao.sessao_status}' não aceito. Aceitos:`, statusesValidos);
  return [];
}

console.log("✅ Status aceito:", sessao.sessao_status);

// --- VALIDAÇÃO DE ROW ---
if (!sessao.row_to_delete || sessao.row_to_delete < 2) {
  console.log("❌ Row inválida:", sessao.row_to_delete);
  return [];
}

console.log("✅ Row válida:", sessao.row_to_delete);

// --- DEFINIÇÃO DE AÇÃO ---
let acaoRealizada;
if (intencao === "CONFIRMADO") acaoRealizada = "Confirmação";
else if (intencao === "CANCELADO") acaoRealizada = "Cancelamento";
else if (intencao === "REMARCAR") acaoRealizada = "Remarcação";
else if (sessao.sessao_status.includes("EXPIRADA") || sessao.sessao_status.includes("Expirada")) {
  acaoRealizada = "Sessão Expirada";
} else {
  acaoRealizada = "Outro";
}

console.log(`✅ RETORNANDO: ${sessao.telefone} - ${acaoRealizada}`);

// --- RETORNO ---
return [{
  json: {
    row: sessao.row_to_delete,
    Telefone: sessao.telefone,
    Nome: nomePaciente,
    "Ação": acaoRealizada,
    "Mensagem do Usuário": mensagemUsuario,
    "Intenção Detectada": intencao,
    "Confiança %": confianca
  }
}];

const row = items[0].json;

// Se n?o encontrou sess?o
if (!row || !row.expira_em) {
  return [{
    json: {
      ...items[0].json,
      sessao_status: "NAO_ENCONTRADA",
      deve_processar: false
    }
  }];
}

// Compara com agora
const agora = new Date();
const expiracao = new Date(row.expira_em); // funciona com ISO 8601

if (agora > expiracao) {
  return [{
    json: {
      ...items[0].json,
      sessao_status: "EXPIRADA",
      deve_processar: false
    }
  }];
}

// Sess?o v?lida
return [{
  json: {
    ...items[0].json,
    sessao_status: "ATIVA",
    deve_processar: true
  }
}];

// ============================================================================
// NÓ: FILTRO ANTI-LOOP EVOLUTION API v3.1 (Case-Insensitive Payload Support)
// ============================================================================

const body = items[0].json.body;
const data = body?.data;

if (!data) {
  console.log("❌ Bloqueado: Payload inválido");
  return [];
}

// Get JID of the sender. Supports PascalCase (Info.Chat) and camelCase (key.remoteJid)
const remoteJid = data.Info?.Chat || data.key?.remoteJid || "";

// --- VALIDAÇÃO 1: É grupo ou broadcast? ---
const isGroup = remoteJid.endsWith("@g.us");
const isBroadcast = remoteJid.endsWith("@broadcast");

if (isGroup || isBroadcast) {
  console.log("🚫 Bloqueado: Mensagem de grupo/broadcast");
  return [];
}

// --- VALIDAÇÃO 2: Tem algum conteúdo válido? ---
const message = data.Message || data.message || {};
const hasText = !!(message.conversation || message.extendedTextMessage?.text || message.Conversation || (message.ExtendedTextMessage || message.extendedTextMessage)?.text || (message.ExtendedTextMessage || message.extendedTextMessage)?.Text);
const hasImage = !!(message.imageMessage || message.ImageMessage);
const hasVideo = !!(message.videoMessage || message.VideoMessage);
const hasAudio = !!(message.audioMessage || message.pttMessage || message.AudioMessage || message.PttMessage || message.pttMessage);
const hasDocument = !!(message.documentMessage || message.DocumentMessage);

if (!hasText && !hasImage && !hasVideo && !hasAudio && !hasDocument) {
  console.log("🚫 Bloqueado: Mensagem sem conteúdo suportado");
  return [];
}

// --- VALIDAÇÃO 3: Não é mensagem enviada por nós (fromMe) ---
// Comentado para permitir testes locais se o usuário responder de si mesmo, 
// mas descomentado para produção normal. 
// const fromMe = (data.Info?.IsFromMe === true) || (data.key?.fromMe === true);
// if (fromMe) {
//   console.log("🚫 Bloqueado: Mensagem enviada pelo próprio sistema");
//   return [];
// }

console.log("✅ Aprovado: Mensagem legítima de", remoteJid);
return items;

