// ============================================================================
// NORMALIZAÇÃO EVOLUTION API v3.1 - FIX: Case-Insensitive Payload Support
// ============================================================================

const DELAY_MS = 650;
await new Promise(resolve => setTimeout(resolve, DELAY_MS));

const body = items[0].json.body;
const data = body?.data;

if (!data) {
  throw new Error("Payload da Evolution API inválido");
}

const message = data.Message || data.message || {};

// --- EXTRAÇÃO DE MENSAGEM ---
let textoMensagem = "";

const conv = message.Conversation || message.conversation;
const extTxtMsg = message.ExtendedTextMessage || message.extendedTextMessage;
const imgMsg = message.ImageMessage || message.imageMessage;
const vidMsg = message.VideoMessage || message.videoMessage;
const audMsg = message.AudioMessage || message.audioMessage || message.PttMessage || message.pttMessage;
const docMsg = message.DocumentMessage || message.documentMessage;

if (conv) {
    textoMensagem = conv;
} else if (extTxtMsg?.text || extTxtMsg?.Text) {
    textoMensagem = extTxtMsg.text || extTxtMsg.Text;
} else if (imgMsg) {
    textoMensagem = imgMsg.caption || imgMsg.Caption || "[IMAGEM RECEBIDA]";
} else if (vidMsg) {
    textoMensagem = vidMsg.caption || vidMsg.Caption || "[VÍDEO RECEBIDO]";
} else if (audMsg) {
    textoMensagem = "[ÁUDIO RECEBIDO]";
} else if (docMsg) {
    textoMensagem = docMsg.caption || docMsg.Caption || "[DOCUMENTO RECEBIDO]";
} else {
    textoMensagem = "[MÍDIA RECEBIDA]";
}

const pushName = data.Info?.PushName || data.pushName || "Paciente";
const instancia = body.instance || "Pessoal";

// --- TELEFONE ---
const remoteJid = data.Info?.Chat || data.key?.remoteJid || "";
let phoneRaw = remoteJid.split('@')[0];

// Remove sufixo se houver e limpa caracteres
let telefone = phoneRaw.replace(/\D/g, '');
let telefonePadronizado = "";

if (telefone.startsWith("55")) {
  const semDDI = telefone.substring(2);
  if (semDDI.length === 10) {
    const ddd = semDDI.substring(0, 2);
    const numero = semDDI.substring(2);
    telefonePadronizado = `55${ddd}9${numero}`;
  } else {
    telefonePadronizado = telefone;
  }
} else {
  if (telefone.length === 10) {
    const ddd = telefone.substring(0, 2);
    const numero = telefone.substring(2);
    telefonePadronizado = `55${ddd}9${numero}`;
  } else if (telefone.length === 11) {
    telefonePadronizado = `55${telefone}`;
  } else {
    telefonePadronizado = `55${telefone}`;
  }
}

const agora = new Date();
const dataLegivel = agora.toLocaleString("pt-BR", { 
