// ============================================================================
// NORMALIZAÇÃO EVOLUTION API v3.1 - FIX: Case-Insensitive Payload Support
// ============================================================================

const DELAY_MS = 650;
await new Promise(resolve => setTimeout(resolve, DELAY_MS));

const body = items[0].json.body;
const data = body?.data;

if (!data) {
  throw new Error("Payload da Evolution API inválido");
}

const message = data.Message || data.message || {};

// --- EXTRAÇÃO DE MENSAGEM ---
let textoMensagem = "";

const conv = message.Conversation || message.conversation;
const extTxtMsg = message.ExtendedTextMessage || message.extendedTextMessage;
const imgMsg = message.ImageMessage || message.imageMessage;
const vidMsg = message.VideoMessage || message.videoMessage;
const audMsg = message.AudioMessage || message.audioMessage || message.PttMessage || message.pttMessage;
const docMsg = message.DocumentMessage || message.documentMessage;

if (conv) {
    textoMensagem = conv;
} else if (extTxtMsg?.text || extTxtMsg?.Text) {
    textoMensagem = extTxtMsg.text || extTxtMsg.Text;
} else if (imgMsg) {
    textoMensagem = imgMsg.caption || imgMsg.Caption || "[IMAGEM RECEBIDA]";
} else if (vidMsg) {
    textoMensagem = vidMsg.caption || vidMsg.Caption || "[VÍDEO RECEBIDO]";
} else if (audMsg) {
    textoMensagem = "[ÁUDIO RECEBIDO]";
} else if (docMsg) {
    textoMensagem = docMsg.caption || docMsg.Caption || "[DOCUMENTO RECEBIDO]";
} else {
    textoMensagem = "[MÍDIA RECEBIDA]";
}

const pushName = data.Info?.PushName || data.pushName || "Paciente";
const instancia = body.instance || "Pessoal";

// --- TELEFONE ---
const remoteJid = data.Info?.Chat || data.key?.remoteJid || "";
let phoneRaw = remoteJid.split('@')[0];

// Remove sufixo se houver e limpa caracteres
let telefone = phoneRaw.replace(/\D/g, '');
let telefonePadronizado = "";

if (telefone.startsWith("55")) {
  const semDDI = telefone.substring(2);
  if (semDDI.length === 10) {
    const ddd = semDDI.substring(0, 2);
    const numero = semDDI.substring(2);
    telefonePadronizado = `55${ddd}9${numero}`;
  } else {
    telefonePadronizado = telefone;
  }
} else {
  if (telefone.length === 10) {
    const ddd = telefone.substring(0, 2);
    const numero = telefone.substring(2);
    telefonePadronizado = `55${ddd}9${numero}`;
  } else if (telefone.length === 11) {
    telefonePadronizado = `55${telefone}`;
  } else {
    telefonePadronizado = `55${telefone}`;
  }
}

const agora = new Date();
const dataLegivel = agora.toLocaleString("pt-BR", { 
    timeZone: "America/Sao_Paulo",
    day: "2-digit", month: "2-digit", year: "numeric",
    hour: "2-digit", minute: "2-digit", second: "2-digit"
});

return {
    json: {
        mensagem_do_usuario: textoMensagem,
        nome_paciente: pushName,
        telefone_whatsapp: telefonePadronizado,
        remote_jid: phoneRaw,
        instancia: instancia,
        timestamp: agora.toISOString(),
        data_hora_legivel: dataLegivel,

        // Debug para compatibilidade
        _z_api_debug: {
            phone_original: remoteJid,
            connected_phone: remoteJid,
            from_me: (data.Info?.IsFromMe === true) || (data.key?.fromMe === true),
            phone_usado: phoneRaw,
            message_id: data.Info?.ID || data.key?.id
        }
    }
};

const dados = $('LOG DE ERRO').item.json;
const trigger = $('Error Trigger').item.json;

// Captura os dados já logados no Supabase
const workflow = dados.workflow_name || 'Desconhecido';
const noComErro = dados.node_name || 'Desconhecido';
const mensagemErro = dados.error_message || 'Sem mensagem';
const executionId = dados.execution_id || '';
const dataHora = dados.criado_em || '';

// Captura dados mais detalhados direto do trigger
const stackTrace = trigger.execution?.error?.stack || 'Stack trace não disponível';
const tipoNo = trigger.execution?.error?.node?.type || 'Tipo desconhecido';
const parametrosNo = JSON.stringify(trigger.execution?.error?.node?.parameters || {}, null, 2);

// PROMPT REFINADO PARA RETORNAR HTML PERFEITO
const prompt = `Atue como um Engenheiro DevOps e Especialista Sênior em n8n. 
Ocorreu um erro crítico em um dos fluxos de produção (um sistema B2B de agendamento de clínicas via Evolution API e Supabase).

Seu objetivo é analisar o erro abaixo, diagnosticar a causa raiz e me dar a solução exata.

⚠️ DADOS DO ERRO:
- Workflow: ${workflow}
- Nó que Falhou: ${noComErro}
- Tipo do Nó: ${tipoNo}
- Mensagem de Erro: ${mensagemErro}
- Stack Trace: ${stackTrace}

⚠️ PARÂMETROS DO NÓ NA HORA DA FALHA:
${parametrosNo}

INSTRUÇÕES DE SAÍDA:
Sua resposta vai ser enviada diretamente para um corpo de e-mail. Por isso, formate o texto EXCLUSIVAMENTE em HTML válido (não use Markdown com asteriscos). 

Siga exatamente esta estrutura:
<p><b>⚠️ O QUE ACONTECEU (Causa Raiz):</b><br>
(Explique em 1 ou 2 frases curtas qual foi a falha técnica).</p>

<p><b>🛠️ COMO CORRIGIR AGORA (Passo a Passo):</b><br>
(Dê a instrução exata do que eu devo clicar ou alterar no n8n usando uma lista numerada <ol><li>...</li></ol>).</p>

<p><b>🛡️ COMO PREVENIR NO FUTURO:</b><br>
(Diga o que eu devo adicionar ao meu fluxo para esse erro não travar o sistema de novo).</p>
`;

return [{
  json: {
    prompt,
    workflow,
    urlExecucao: `https://n8n.iagobatista.cloud/execution/${executionId}`
  }
}];

