const consultas = items.map(item => {
  const c = item.json;
  const p = c.patient || {};

  if (!p.telefone) {
    return {
      json: {
        valido: false,
        erro: "Paciente sem telefone cadastrado"
      }
    };
  }

  const dataObj = new Date(c.data_hora);
  const diaFormatado = dataObj.toLocaleDateString('pt-BR', { 
    day: '2-digit', 
    month: '2-digit', 
    year: 'numeric', 
    timeZone: 'America/Sao_Paulo' 
  });
  const horaFormatada = dataObj.toLocaleTimeString('pt-BR', { 
    hour: '2-digit', 
    minute: '2-digit', 
    timeZone: 'America/Sao_Paulo' 
  });

  return {
    json: {
      valido: true,
      erro: null,
      nome_completo: p.nome || 'Paciente',
      primeiro_nome: (p.nome || 'Paciente').split(' ')[0],
      telefone_whatsapp: '55' + p.telefone.replace(/\D/g, ''),
      telefone_formatado: p.telefone || '',
      dia_consulta: diaFormatado,
      hora_consulta: horaFormatada,
      mensagem_data: `dia ${diaFormatado} às ${horaFormatada}`,
      google_event_id: c.id,
      cor_atual: c.status,
      titulo_original: `${p.nome} - ${c.tipo}`,
      medico: c.medico || 'seu médico',
      tipo: c.tipo || 'consulta'
    }
  };
});

return consultas.filter(c => c.json.valido);

// ============================================================================
// N?: ABRE SESS?O DE CONFIRMA??O v2.0 - MULTI-ITEM PROCESSING
// Fix: Processar TODOS os eventos, n?o apenas items[0]
// ============================================================================

// ? LOOP ATRAV?S DE TODOS OS ITENS
const resultados = items.map(item => {
  const telefone = item.json.telefone_whatsapp;
  const googleEventId = item.json.google_event_id;

  if (!telefone) {
    return {
      json: {
        erro: "Telefone n?o encontrado",
        ...item.json
      }
    };
  }

const agora = Date.now();
const expiraEm = agora + (16 * 60 * 60 * 1000); // 16 horas

  // Retorna dados da sess?o + passa todos os dados do item
  return {
    json: {
      sessao_telefone: telefone,
      sessao_evento_id: googleEventId,
      sessao_timestamp: agora,
      sessao_expira_em: expiraEm,
      deve_salvar_sessao: true,
      ...item.json  // ? Passa TODOS os dados (nome, data, etc)
    }
  };
});

// ? RETORNA TODOS OS RESULTADOS
return resultados;

// ============================================================================
// LOG CRM: Upsert Conversa + Log/Update Mensagem no Cliniflow v2.5 (Deduplicated)
// ============================================================================

const SUPABASE_URL = 'https://mxvaufkqijdkapvtkvee.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im14dmF1ZmtxaWpka2FwdnRrdmVlIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0MjEzMDAsImV4cCI6MjA4ODk5NzMwMH0.CVl3Qechh91cZA9AXfMrNmnCMgGFCyROaSB4AqU9c3I';
const CLINIC_ID = 'd3b07384-ad6b-4f5c-9ab4-66e2854d88ad';

const patientId = $('Busca Paciente').first().json.id;
const phone = $('Normalizar Dados v2').first().json.telefone_whatsapp;
const mensagem = $('Normalizar Dados v2').first().json.mensagem_do_usuario || '';
const now = new Date().toISOString();

// Get the unique message ID from Evolution API debug data
let evoMessageId = null;
try {
  const normData = $('Normalizar Dados v2').first().json;
  evoMessageId = normData._z_api_debug ? normData._z_api_debug.message_id : null;
} catch (e) {
  // Ignore
}

if (!patientId) {
  return $input.all();
}

let intencao = 'DESCONHECIDO';
let confianca = 0;
try {
  const validaJson = $('Valida contexto').first().json;
  intencao = validaJson.intencao_detectada || 'DESCONHECIDO';
  confianca = validaJson.confianca_percentual || 0;
} catch (e) {
  // Ignore
}

const sbHeaders = {
  'apikey': SUPABASE_KEY,
  'Authorization': 'Bearer ' + SUPABASE_KEY,
  'Content-Type': 'application/json'
};

// 1. Busca conversa aberta para este paciente
let conversa_id = null;
try {
  const buscaResp = await this.helpers.httpRequest({
    method: 'GET',
    url: SUPABASE_URL + '/rest/v1/conversations?patient_id=eq.' + patientId + '&status=eq.open&limit=1&select=id',
    headers: sbHeaders,
    json: true
  });

  const conversas = Array.isArray(buscaResp) ? buscaResp : [];

  if (conversas.length > 0 && conversas[0].id) {
    conversa_id = conversas[0].id;
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SUPABASE_URL + '/rest/v1/conversations?id=eq.' + conversa_id,
      headers: Object.assign({}, sbHeaders, { 'Prefer': 'return=minimal' }),
      body: { last_activity_at: now },
      json: true
    });
  } else {
    const criaResp = await this.helpers.httpRequest({
      method: 'POST',
      url: SUPABASE_URL + '/rest/v1/conversations',
      headers: Object.assign({}, sbHeaders, { 'Prefer': 'return=representation' }),
      body: {
        clinic_id: CLINIC_ID,
        patient_id: patientId,
        status: 'open',
        last_activity_at: now
      },
      json: true
    });
    const criadas = Array.isArray(criaResp) ? criaResp : [criaResp];
    conversa_id = criadas[0]?.id || null;
  }
} catch (e) {
  console.error('[CRM] Erro no upsert de conversa:', e.message);
}

// 2. Loga ou atualiza a mensagem recebida
if (conversa_id && mensagem) {
  try {
    let messageLogId = null;
    let existingIntent = null;

    // Check if message with this evoMessageId already exists
    if (evoMessageId) {
      const checkResp = await this.helpers.httpRequest({
        method: 'GET',
        url: SUPABASE_URL + '/rest/v1/mensagem_logs?evo_message_id=eq.' + evoMessageId + '&select=id,intencao_detectada',
        headers: sbHeaders,
        json: true
      });
      const existing = Array.isArray(checkResp) ? checkResp : [];
      if (existing.length > 0) {
        messageLogId = existing[0].id;
        existingIntent = existing[0].intencao_detectada;
      }
    }

    if (messageLogId) {
      // If the intent has been updated (e.g. from DESCONHECIDO to CONFIRMADO)
      if (existingIntent !== intencao) {
        await this.helpers.httpRequest({
          method: 'PATCH',
          url: SUPABASE_URL + '/rest/v1/mensagem_logs?id=eq.' + messageLogId,
          headers: Object.assign({}, sbHeaders, { 'Prefer': 'return=minimal' }),
          body: {
            intencao_detectada: intencao,
            confianca_percentual: confianca
          },
          json: true
        });
        console.log('[CRM] Log de mensagem atualizado com a intenção detectada:', intencao);
      }
    } else {
      // Create new message log
      await this.helpers.httpRequest({
        method: 'POST',
        url: SUPABASE_URL + '/rest/v1/mensagem_logs',
        headers: Object.assign({}, sbHeaders, { 'Prefer': 'return=minimal' }),
        body: {
          conversation_id: conversa_id,
          patient_id: patientId,
          telefone: phone,
          mensagem: mensagem,
          direcao: 'entrada',
          tipo: 'manual',
          private: false,
          intencao_detectada: intencao,
          confianca_percentual: confianca,
          evo_message_id: evoMessageId
        },
        json: true
      });
      console.log('[CRM] Novo log de mensagem criado');
    }
  } catch (e) {
    console.error('[CRM] Erro ao logar/atualizar mensagem:', e.message);
  }
}

return $input.all();
